insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('vale-un-acuerdo-verbal-o-un-mensaje-de-whatsapp-como-contrato','derecho',array['tecnologia','negocios']::text[],'¿Vale un acuerdo verbal o un mensaje de WhatsApp como contrato?','Analiza si los acuerdos hechos de palabra o por mensajes tienen valor, cuándo pueden servir como prueba y qué conviene dejar por escrito para evitar conflictos.','Análisis','~16 h',16,array['Acuerdos','Pruebas digitales']::text[],array['investigar']::text[],'publicos',NULL,'derecho ingenieria de sistemas administracion comunicaciones economia contabilidad psicologia educacion lectura de normas. analisis de casos. redaccion formal. pensamiento critico. fuentes oficiales. un editor de documentos. casos inventados.',$a66sld${"id": "vale-un-acuerdo-verbal-o-un-mensaje-de-whatsapp-como-contrato", "area": "derecho", "areas2": ["tecnologia", "negocios"], "titulo": "¿Vale un acuerdo verbal o un mensaje de WhatsApp como contrato?", "resumen": "Analiza si los acuerdos hechos de palabra o por mensajes tienen valor, cuándo pueden servir como prueba y qué conviene dejar por escrito para evitar conflictos.", "tipo": "Análisis", "tiempo": "~16 h", "horas": 16, "etiquetas": ["Acuerdos", "Pruebas digitales"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ingeniería de Sistemas", "Administración", "Comunicaciones", "Economía", "Contabilidad", "Psicología", "Educación"], "problema": ["Muchos acuerdos cotidianos, como un alquiler de cuarto, un trabajo freelance o una venta entre conocidos, se cierran por chat o de palabra. Cuando surge un problema, aparece la duda de si eso valía y cómo demostrarlo.", "Entender el valor y los límites de estos acuerdos ayuda a protegerse."], "desarrollar": ["Con fuentes oficiales y material informativo, resume cuándo un acuerdo verbal o digital es válido, qué dificultades hay para probarlo y qué elementos conviene registrar.", "Redacta cinco casos inventados, como un trabajo por encargo o una venta por redes, y explica qué evidencia ayudaría y qué se debió acordar por escrito."], "ampliaciones": [{"titulo": "Plantilla simple", "aporta": "crea un modelo de confirmación escrita tras un acuerdo verbal."}, {"titulo": "Capturas y pruebas", "aporta": "explica qué cuidados tener al guardar conversaciones."}, {"titulo": "Cuándo exigir un escrito", "aporta": "lista casos donde la ley pide forma escrita."}], "objetivos": ["Comprender el valor de acuerdos informales.", "Identificar límites y riesgos.", "Proponer buenas prácticas.", "Explicar con claridad."], "habilidades": ["Lectura de normas.", "Análisis de casos.", "Redacción formal.", "Pensamiento crítico."], "herramientas": ["Fuentes oficiales.", "Un editor de documentos.", "Casos inventados."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas, plazos y montos cambian.", "Trabaja con casos inventados y sin datos personales de nadie."], "otroSector": "El mismo análisis sirve para acuerdos entre socios de un proyecto o entre compañeros de un trabajo grupal."}$a66sld$::jsonb,68),
('ciberacoso-y-violencia-digital-que-dice-la-ley-y-adonde-acudir','derecho',array['tecnologia','sociedad']::text[],'Ciberacoso y violencia digital: qué dice la ley y adónde acudir','Reúne información oficial sobre qué conductas se consideran acoso o violencia digital, qué recursos existen para denunciar o pedir ayuda y cómo cuidar las pruebas.','Guía','~20 h',20,array['Ciberacoso','Violencia digital']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho psicologia ingenieria de sistemas educacion trabajo social comunicaciones sociologia administracion lectura de normas. redaccion sensible. diseno de guias. empatia. portales oficiales. un editor de documentos. un editor de infografias.',$a67sld${"id": "ciberacoso-y-violencia-digital-que-dice-la-ley-y-adonde-acudir", "area": "derecho", "areas2": ["tecnologia", "sociedad"], "titulo": "Ciberacoso y violencia digital: qué dice la ley y adónde acudir", "resumen": "Reúne información oficial sobre qué conductas se consideran acoso o violencia digital, qué recursos existen para denunciar o pedir ayuda y cómo cuidar las pruebas.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Ciberacoso", "Violencia digital"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Psicología", "Ingeniería de Sistemas", "Educación", "Trabajo Social", "Comunicaciones", "Sociología", "Administración"], "problema": ["Insultos, amenazas, difusión de fotos sin permiso o suplantación de identidad en redes pueden causar un daño grave. Muchas víctimas no saben que existen normas ni a quién acudir, y otras borran las pruebas por vergüenza o miedo.", "Una guía clara de recursos oficiales ayuda a actuar con más seguridad."], "desarrollar": ["Con fuentes oficiales, describe las conductas que se reconocen como violencia digital, las instituciones y líneas de atención, los pasos para denunciar y cómo conservar pruebas.", "Diseña una guía breve, respetuosa y sin casos reales, con preguntas frecuentes, y pruébala con compañeros para comprobar que se entiende y no revictimiza."], "ampliaciones": [{"titulo": "Para quien presencia", "aporta": "añade qué puede hacer alguien que ve acoso."}, {"titulo": "Para familias y docentes", "aporta": "adapta la guía para madres, padres y docentes."}, {"titulo": "Configuración de privacidad", "aporta": "suma pasos de protección en redes."}], "objetivos": ["Reconocer conductas de violencia digital.", "Conocer recursos de ayuda.", "Explicar cómo conservar pruebas.", "Redactar con sensibilidad."], "habilidades": ["Lectura de normas.", "Redacción sensible.", "Diseño de guías.", "Empatía."], "herramientas": ["Portales oficiales.", "Un editor de documentos.", "Un editor de infografías."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas, plazos y montos cambian.", "No uses casos reales ni nombres, trata el tema con respeto y recuerda que quien necesite ayuda urgente debe acudir a los servicios oficiales de atención."], "otroSector": "La misma guía sirve para otros riesgos digitales como la suplantación o la difusión de imágenes sin permiso."}$a67sld$::jsonb,69),
('estafas-por-internet-como-reconocerlas-y-que-hacer','derecho',array['tecnologia','sociedad']::text[],'Estafas por internet: cómo reconocerlas y qué hacer','Cataloga las estafas más comunes por internet, como falsas ofertas, suplantación de bancos o tiendas falsas, enseña a reconocer sus señales y explica a quién acudir si ocurren.','Guía','~18 h',18,array['Estafas','Seguridad digital']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho ingenieria de sistemas comunicaciones educacion administracion psicologia economia trabajo social pensamiento critico. seguridad digital basica. diseno de guias. redaccion clara. alertas oficiales. un editor de infografias. un formulario de practica.',$a68sld${"id": "estafas-por-internet-como-reconocerlas-y-que-hacer", "area": "derecho", "areas2": ["tecnologia", "sociedad"], "titulo": "Estafas por internet: cómo reconocerlas y qué hacer", "resumen": "Cataloga las estafas más comunes por internet, como falsas ofertas, suplantación de bancos o tiendas falsas, enseña a reconocer sus señales y explica a quién acudir si ocurren.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Estafas", "Seguridad digital"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ingeniería de Sistemas", "Comunicaciones", "Educación", "Administración", "Psicología", "Economía", "Trabajo Social"], "problema": ["Mensajes que prometen premios, tiendas con precios imposibles o llamadas que se hacen pasar por un banco son cada vez más frecuentes. Quien cae suele sentir vergüenza y no denuncia, y las estafas se repiten.", "Reconocer patrones y saber qué hacer reduce el riesgo y la pérdida."], "desarrollar": ["Con fuentes oficiales y alertas públicas, describe ocho tipos de estafa con un ejemplo inventado de cada una, sus señales de alerta y cómo verificar antes de actuar.", "Elabora una guía con una lista de comprobación de cinco preguntas y los pasos a seguir si ya se cayó, como contactar al banco, guardar pruebas y denunciar ante la autoridad."], "ampliaciones": [{"titulo": "Test de reconocimiento", "aporta": "crea un cuestionario con mensajes inventados para practicar."}, {"titulo": "Para personas mayores", "aporta": "adapta la guía a familiares con menos experiencia digital."}, {"titulo": "Tiendas verificadas", "aporta": "explica cómo comprobar si un comercio en línea es real."}], "objetivos": ["Reconocer tipos de estafa.", "Aplicar una lista de comprobación.", "Conocer pasos de reacción.", "Comunicar con claridad."], "habilidades": ["Pensamiento crítico.", "Seguridad digital básica.", "Diseño de guías.", "Redacción clara."], "herramientas": ["Alertas oficiales.", "Un editor de infografías.", "Un formulario de práctica."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas, plazos y montos cambian.", "Usa ejemplos inventados y evita reproducir enlaces o datos reales de estafadores."], "otroSector": "La misma guía sirve para prevención en empresas, colegios o comunidades."}$a68sld$::jsonb,70),
('conciliacion-y-mediacion-resolver-un-conflicto-sin-ir-a-juicio','derecho',array['sociedad']::text[],'Conciliación y mediación: resolver un conflicto sin ir a juicio','Explica qué son la conciliación y la mediación, cuándo sirven, cómo es una sesión y qué diferencias hay con un juicio, con ejemplos de conflictos cotidianos.','Guía','~20 h',20,array['Conciliación','Mediación']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho psicologia sociologia trabajo social administracion educacion comunicaciones ingenieria industrial lectura de normas. comunicacion y negociacion. analisis de casos. redaccion de guiones. portales oficiales. un editor de documentos. casos inventados.',$a69sld${"id": "conciliacion-y-mediacion-resolver-un-conflicto-sin-ir-a-juicio", "area": "derecho", "areas2": ["sociedad"], "titulo": "Conciliación y mediación: resolver un conflicto sin ir a juicio", "resumen": "Explica qué son la conciliación y la mediación, cuándo sirven, cómo es una sesión y qué diferencias hay con un juicio, con ejemplos de conflictos cotidianos.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Conciliación", "Mediación"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Psicología", "Sociología", "Trabajo Social", "Administración", "Educación", "Comunicaciones", "Ingeniería Industrial"], "problema": ["Un conflicto por una deuda, un contrato, una vivienda o un servicio no siempre necesita llegar a un juicio. Existen formas de resolverlo con ayuda de un tercero, que suelen ser más rápidas y baratas, pero poca gente las conoce.", "Entender cómo funcionan ayuda a decidir qué camino conviene."], "desarrollar": ["Con fuentes oficiales, describe qué es cada mecanismo, quién interviene, qué costos y plazos suele tener y qué efecto tiene un acuerdo alcanzado.", "Prepara un guion de una sesión de conciliación inventada con roles de ejemplo, un cuadro comparativo con el juicio y cinco casos cotidianos en los que podría servir."], "ampliaciones": [{"titulo": "Simulación", "aporta": "organiza un juego de roles para practicar una sesión."}, {"titulo": "Cómo prepararse", "aporta": "lista qué llevar y cómo comunicarse en una sesión."}, {"titulo": "Conflictos entre vecinos", "aporta": "aplica el análisis a un caso vecinal."}], "objetivos": ["Conocer mecanismos de solución de conflictos.", "Compararlos con un juicio.", "Aplicarlos a casos.", "Practicar una sesión."], "habilidades": ["Lectura de normas.", "Comunicación y negociación.", "Análisis de casos.", "Redacción de guiones."], "herramientas": ["Portales oficiales.", "Un editor de documentos.", "Casos inventados."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas, plazos y montos cambian.", "Usa casos inventados y no incluyas conflictos reales de personas conocidas."], "otroSector": "La misma guía sirve para resolver conflictos dentro de equipos de trabajo o de una organización."}$a69sld$::jsonb,71),
('registrar-una-marca-cuanto-cuesta-cuanto-demora-y-como-se-hace','derecho',array['negocios','arte']::text[],'Registrar una marca: cuánto cuesta, cuánto demora y cómo se hace','Describe paso a paso cómo se registra una marca, qué se puede y qué no registrar, cuánto suele costar y demorar, y qué beneficios da a un emprendimiento.','Guía','~18 h',18,array['Marcas','Emprendimiento']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho administracion diseno ingenieria industrial economia comunicaciones ingenieria de sistemas contabilidad lectura de normas. busqueda en registros publicos. planificacion. pensamiento de negocio. portal de la autoridad de propiedad intelectual. hoja de calculo. un editor de documentos.',$a70sld${"id": "registrar-una-marca-cuanto-cuesta-cuanto-demora-y-como-se-hace", "area": "derecho", "areas2": ["negocios", "arte"], "titulo": "Registrar una marca: cuánto cuesta, cuánto demora y cómo se hace", "resumen": "Describe paso a paso cómo se registra una marca, qué se puede y qué no registrar, cuánto suele costar y demorar, y qué beneficios da a un emprendimiento.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Marcas", "Emprendimiento"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Diseño", "Ingeniería Industrial", "Economía", "Comunicaciones", "Ingeniería de Sistemas", "Contabilidad"], "problema": ["Quien lanza un negocio suele elegir un nombre y un logo sin verificar si ya existen ni protegerlos. Después puede enfrentar conflictos, o perder el nombre que ya había posicionado.", "Conocer el proceso de registro permite decidir a tiempo."], "desarrollar": ["Con fuentes oficiales, resume qué es una marca, cómo se busca si un nombre ya está registrado, qué documentos y tasas se requieren y cuáles son las etapas del trámite.", "Simula el proceso con un emprendimiento inventado, desde la búsqueda hasta la solicitud, y arma una lista de errores frecuentes como nombres genéricos o muy parecidos a otros."], "ampliaciones": [{"titulo": "Costos y plazos", "aporta": "estima el presupuesto total y la duración."}, {"titulo": "Nombre y logo", "aporta": "da criterios para elegir un signo registrable."}, {"titulo": "Otros países", "aporta": "explica cómo proteger la marca fuera del país."}], "objetivos": ["Conocer el proceso de registro.", "Realizar una búsqueda previa.", "Simular el trámite.", "Anticipar errores."], "habilidades": ["Lectura de normas.", "Búsqueda en registros públicos.", "Planificación.", "Pensamiento de negocio."], "herramientas": ["Portal de la autoridad de propiedad intelectual.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas, plazos y montos cambian.", "Los costos y plazos cambian: cita la fecha de consulta y no los presentes como definitivos."], "otroSector": "El mismo proceso sirve para entender el registro de nombres comerciales o de dominios."}$a70sld$::jsonb,72),
('quien-responde-cuando-falla-un-sistema-o-una-decision-automatiza','derecho',array['tecnologia']::text[],'¿Quién responde cuando falla un sistema o una decisión automatizada?','Analiza quién tiene responsabilidad cuando un sistema informático o un algoritmo comete un error que afecta a una persona, como un cobro indebido o una decisión automatizada, y qué se puede reclamar.','Análisis','~24 h',24,array['Responsabilidad','Sistemas automatizados']::text[],array['investigar']::text[],'publicos',NULL,'derecho ingenieria de sistemas ciencia de datos administracion ciencias politicas filosofia comunicaciones ingenieria industrial analisis de casos. pensamiento etico. lectura de normas. diseno responsable. fuentes oficiales. un editor de diagramas. un editor de documentos.',$a71sld${"id": "quien-responde-cuando-falla-un-sistema-o-una-decision-automatiza", "area": "derecho", "areas2": ["tecnologia"], "titulo": "¿Quién responde cuando falla un sistema o una decisión automatizada?", "resumen": "Analiza quién tiene responsabilidad cuando un sistema informático o un algoritmo comete un error que afecta a una persona, como un cobro indebido o una decisión automatizada, y qué se puede reclamar.", "tipo": "Análisis", "tiempo": "~24 h", "horas": 24, "etiquetas": ["Responsabilidad", "Sistemas automatizados"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ingeniería de Sistemas", "Ciencia de Datos", "Administración", "Ciencias Políticas", "Filosofía", "Comunicaciones", "Ingeniería Industrial"], "problema": ["Cada vez más decisiones se apoyan en sistemas: aprobar un crédito, filtrar un currículum, bloquear una cuenta. Cuando fallan, la persona afectada no sabe a quién reclamar: ¿a la empresa, al proveedor del software o a nadie?", "Entender cómo se reparten las responsabilidades ayuda a diseñar mejores sistemas y a reclamar con fundamento."], "desarrollar": ["Con fuentes oficiales y casos públicos y anónimos, resume cómo se discute la responsabilidad en errores de sistemas y qué derechos tienen las personas frente a decisiones automatizadas.", "Analiza cinco casos inventados, como un cobro duplicado, un bloqueo injustificado o un filtro de postulantes, e identifica quiénes intervienen, quién podría responder y qué prueba ayudaría a reclamar."], "ampliaciones": [{"titulo": "Cómo diseñar con responsabilidad", "aporta": "propón prácticas para que un sistema permita reclamos y revisión humana."}, {"titulo": "Explicabilidad", "aporta": "estudia qué significa poder explicar una decisión automática."}, {"titulo": "Registro de decisiones", "aporta": "propón qué datos guardar para poder auditarlas."}], "objetivos": ["Identificar actores y responsabilidades.", "Analizar casos de fallas.", "Conocer derechos del afectado.", "Proponer buenas prácticas."], "habilidades": ["Análisis de casos.", "Pensamiento ético.", "Lectura de normas.", "Diseño responsable."], "herramientas": ["Fuentes oficiales.", "Un editor de diagramas.", "Un editor de documentos."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas, plazos y montos cambian.", "Usa casos inventados o anónimos y no atribuyas culpa a empresas reales concretas."], "otroSector": "El mismo análisis sirve para evaluar proyectos de software propios, como los de un curso o unas prácticas."}$a71sld$::jsonb,73),
('como-compra-el-estado-una-introduccion-a-las-contrataciones-publ','derecho',array['negocios','ciudades']::text[],'¿Cómo compra el Estado? Una introducción a las contrataciones públicas','Explica cómo contrata el Estado bienes, servicios y obras, qué etapas tiene un proceso de selección y qué información pública se puede consultar en los portales oficiales.','Guía','~24 h',24,array['Contrataciones','Compras públicas']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho administracion ingenieria industrial contabilidad economia ingenieria civil ingenieria de sistemas ciencias politicas lectura de normas. lectura de documentos tecnicos. busqueda de informacion publica. sintesis. portales oficiales de contrataciones. hoja de calculo. un editor de documentos.',$a72sld${"id": "como-compra-el-estado-una-introduccion-a-las-contrataciones-publ", "area": "derecho", "areas2": ["negocios", "ciudades"], "titulo": "¿Cómo compra el Estado? Una introducción a las contrataciones públicas", "resumen": "Explica cómo contrata el Estado bienes, servicios y obras, qué etapas tiene un proceso de selección y qué información pública se puede consultar en los portales oficiales.", "tipo": "Guía", "tiempo": "~24 h", "horas": 24, "etiquetas": ["Contrataciones", "Compras públicas"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Ingeniería Industrial", "Contabilidad", "Economía", "Ingeniería Civil", "Ingeniería de Sistemas", "Ciencias Políticas"], "problema": ["El Estado compra desde útiles escolares hasta carreteras, pero pocas personas saben cómo se decide a quién se contrata. Los procesos tienen etapas, reglas y portales con información pública que casi nadie revisa.", "Entenderlos permite seguir el uso de recursos y abre oportunidades a futuros proveedores."], "desarrollar": ["Con fuentes oficiales, describe las etapas de un proceso de contratación pública, los actores que intervienen y los tipos de procesos, y explica cómo leer una convocatoria.", "Elige una convocatoria pública de ejemplo, resume qué se compra, qué requisitos piden y qué plazos tienen, sin evaluar a ninguna empresa, y arma un glosario de términos clave."], "ampliaciones": [{"titulo": "Seguir un proceso", "aporta": "muestra cómo ubicar el resultado de una convocatoria."}, {"titulo": "Ser proveedor", "aporta": "describe qué debe hacer una pequeña empresa para participar."}, {"titulo": "Comparar tipos", "aporta": "compara procesos por monto y por tipo de contratación."}], "objetivos": ["Conocer etapas de la contratación pública.", "Leer una convocatoria.", "Usar portales oficiales.", "Explicar con claridad."], "habilidades": ["Lectura de normas.", "Lectura de documentos técnicos.", "Búsqueda de información pública.", "Síntesis."], "herramientas": ["Portales oficiales de contrataciones.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Mantén una mirada neutral: describe y compara, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas, plazos y montos cambian.", "Describe el proceso y no evalúes a empresas ni funcionarios concretos."], "otroSector": "El mismo método sirve para entender compras en una universidad o en una empresa grande."}$a72sld$::jsonb,74),
('como-leer-un-plan-de-gobierno-que-promete-como-se-financia-y-si','derecho',array['sociedad','educacion']::text[],'Cómo leer un plan de gobierno: qué promete, cómo se financia y si se puede medir','Enseña un método para leer cualquier plan de gobierno con criterios claros: qué problema identifica, qué propone, cuánto cuesta, cómo se financia y con qué indicadores se mediría, sin juzgar a ninguna opción política.','Guía','~24 h',24,array['Planes de gobierno','Lectura crítica']::text[],array['investigar','crear']::text[],'publicos',NULL,'ciencias politicas derecho economia estadistica sociologia comunicaciones administracion educacion lectura critica. diseno de fichas. analisis de indicadores. neutralidad. documentos publicos. hoja de calculo. un editor de documentos.',$a73sld${"id": "como-leer-un-plan-de-gobierno-que-promete-como-se-financia-y-si", "area": "derecho", "areas2": ["sociedad", "educacion"], "titulo": "Cómo leer un plan de gobierno: qué promete, cómo se financia y si se puede medir", "resumen": "Enseña un método para leer cualquier plan de gobierno con criterios claros: qué problema identifica, qué propone, cuánto cuesta, cómo se financia y con qué indicadores se mediría, sin juzgar a ninguna opción política.", "tipo": "Guía", "tiempo": "~24 h", "horas": 24, "etiquetas": ["Planes de gobierno", "Lectura crítica"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ciencias Políticas", "Derecho", "Economía", "Estadística", "Sociología", "Comunicaciones", "Administración", "Educación"], "problema": ["Los planes de gobierno son documentos largos y llenos de promesas, y mucha gente decide sin leerlos. No saben cómo distinguir una propuesta concreta de una declaración general.", "Un método neutral de lectura permite entender cualquier plan con las mismas preguntas."], "desarrollar": ["Define una lista de preguntas aplicable a cualquier plan: problema, propuesta, responsable, costo, fuente de financiamiento, plazo e indicador, y construye una ficha para anotarlas.", "Prueba la ficha con un plan de ejemplo inventado, y si usas planes reales, aplica los mismos criterios a varios sin comparar su contenido político, solo su claridad y medibilidad."], "ampliaciones": [{"titulo": "Semáforo de claridad", "aporta": "califica cada propuesta según qué tan concreta y medible es."}, {"titulo": "Glosario", "aporta": "explica términos como meta, indicador o línea de base."}, {"titulo": "Aplicarlo a una gestión local", "aporta": "adapta la ficha al plan de una municipalidad."}], "objetivos": ["Definir criterios de lectura.", "Aplicarlos a un plan.", "Evaluar claridad y medibilidad.", "Mantener neutralidad."], "habilidades": ["Lectura crítica.", "Diseño de fichas.", "Análisis de indicadores.", "Neutralidad."], "herramientas": ["Documentos públicos.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Mantén una mirada neutral: describe y compara, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas, plazos y montos cambian.", "Evalúa solo la claridad y la medibilidad de las propuestas, nunca su orientación política, y no hagas llamados a votar."], "otroSector": "La misma ficha sirve para evaluar planes de una organización, de una universidad o de un proyecto."}$a73sld$::jsonb,75)
